    20	@Service
    21	public class CheckoutService {
    22	
    23	    private final ProductRepository productRepository;
    24	    private final OrderRepository orderRepository;
    25	    private final InsuranceService insuranceService;
    26	    private final Map<CouponCode, CouponStrategy> couponStrategies;
    27	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
    28	    private final Map<PaymentMethod, PaymentStrategy> paymentStrategies;
    29	    private final Map<ClubTier, ClubTierStrategy> clubStrategies;
    30	
    31	    public CheckoutService(
    32	            ProductRepository productRepository,
    33	            OrderRepository orderRepository,
    34	            InsuranceService insuranceService,
    35	            List<CouponStrategy> coupons,
    36	            List<ShippingStrategy> shippings,
    37	            List<PaymentStrategy> payments,
    38	            List<ClubTierStrategy> clubs) {
    39	        this.productRepository = productRepository;
    40	        this.orderRepository = orderRepository;
    41	        this.insuranceService = insuranceService;
    42	        this.couponStrategies = coupons.stream()
    43	            .collect(Collectors.toMap(CouponStrategy::getCode, c -> c));
    44	        this.shippingStrategies = shippings.stream()
    45	            .collect(Collectors.toMap(ShippingStrategy::getMethod, s -> s));
    46	        this.paymentStrategies = payments.stream()
    47	            .collect(Collectors.toMap(PaymentStrategy::getMethod, p -> p));
    48	        this.clubStrategies = clubs.stream()
    49	            .collect(Collectors.toMap(ClubTierStrategy::getTier, c -> c));
    50	    }
