    52	    @Transactional(readOnly = true)
    53	    public OrderSummary calculateSummary(OrderRequest request) {
    54	        validateRequest(request);
    55	
    56	        Map<String, Product> products = loadProducts(request);
    57	
    58	        Money productsSubtotal = calculateProductsSubtotal(request.items(), products);
    59	
    60	        Weight totalWeight = calculateTotalWeight(request.items(), products);
    61	
    62	        ClubTierStrategy clubStrategy = getClubStrategy(request.clubTier());
    63	
    64	        ShippingStrategy.ShippingResult shipping = calculateShipping(
    65	            request, totalWeight, clubStrategy
    66	        );
    67	
    68	        Money couponDiscount = calculateCouponDiscount(
    69	            request, productsSubtotal, shipping.cost(), products
    70	        );
    71	
    72	        Money insurance = insuranceService.calculateInsurance(productsSubtotal, request.region());
    73	
    74	        Money orderTotal = productsSubtotal
    75	            .subtract(couponDiscount)
    76	            .add(shipping.cost())
    77	            .add(insurance);
    78	
    79	        PaymentStrategy.PaymentResult payment = calculatePayment(request, orderTotal);
    80	
    81	        Money nextPurchaseCredit = clubStrategy.calculateCredit(productsSubtotal);
    82	        boolean gift = clubStrategy.hasGift(productsSubtotal);
    83	
    84	        return new OrderSummary(
    85	            productsSubtotal,
    86	            couponDiscount,
    87	            shipping.cost(),
    88	            shipping.days(),
    89	            insurance,
    90	            payment.adjustment(),
    91	            payment.finalTotal(),
    92	            request.getInstallments(),
    93	            payment.installmentAmount(),
    94	            nextPurchaseCredit,
    95	            gift
    96	        );
    97	    }
