    99	    private void validateRequest(OrderRequest request) {
   100	        if (request.customer() == null || request.customer().cpf() == null || request.customer().email() == null) {
   101	            throw ErrorCode.INVALID_ORDER.asException();
   102	        }
   103	
   104	        if (request.items() == null || request.items().isEmpty()) {
   105	            throw ErrorCode.INVALID_ORDER.asException();
   106	        }
   107	
   108	        Set<String> seenSkus = new HashSet<>();
   109	        for (var item : request.items()) {
   110	            if (item.sku() == null || item.quantity() == null || item.quantity() <= 0) {
   111	                throw ErrorCode.INVALID_ORDER.asException();
   112	            }
   113	            if (!seenSkus.add(item.sku())) {
   114	                throw ErrorCode.INVALID_ORDER.asException();
   115	            }
   116	        }
   117	    }
   118	
   119	    private Map<String, Product> loadProducts(OrderRequest request) {
   120	        List<String> skus = request.items().stream()
   121	            .map(OrderRequest.ItemInfo::sku)
   122	            .toList();
   123	
   124	        List<Product> products = productRepository.findAllById(skus);
   125	
   126	        if (products.size() != skus.size()) {
   127	            throw ErrorCode.UNKNOWN_PRODUCT.asException();
   128	        }
   129	
   130	        Map<String, Product> productMap = products.stream()
   131	            .collect(Collectors.toMap(Product::getSku, p -> p));
   132	
   133	        for (Product product : products) {
   134	            if (product.isDiscontinued()) {
   135	                throw ErrorCode.PRODUCT_DISCONTINUED.asException();
   136	            }
   137	        }
   138	
   139	        for (var item : request.items()) {
   140	            Product product = productMap.get(item.sku());
   141	            if (!product.hasStock(item.quantity())) {
   142	                throw ErrorCode.INSUFFICIENT_STOCK.asException();
   143	            }
   144	        }
   145	
   146	        return productMap;
   147	    }
   148	
   149	    private Money calculateProductsSubtotal(List<OrderRequest.ItemInfo> items, Map<String, Product> products) {
   150	        Money total = Money.zero();
   151	        for (var item : items) {
   152	            Product product = products.get(item.sku());
   153	            Money itemTotal = product.getPrice().multiply(item.quantity());
   154	            total = total.add(itemTotal);
   155	        }
   156	        return total;
   157	    }
   158	
   159	    private Weight calculateTotalWeight(List<OrderRequest.ItemInfo> items, Map<String, Product> products) {
   160	        Weight total = new Weight(0);
   161	        for (var item : items) {
   162	            Product product = products.get(item.sku());
   163	            Weight itemWeight = product.getWeight().multiply(item.quantity());
   164	            total = total.add(itemWeight);
   165	        }
   166	        return total;
   167	    }
   168	
   169	    private ClubTierStrategy getClubStrategy(ClubTier tier) {
   170	        if (tier == null) {
   171	            throw ErrorCode.INVALID_CLUB_TIER.asException();
   172	        }
   173	        ClubTierStrategy strategy = clubStrategies.get(tier);
   174	        if (strategy == null) {
   175	            throw ErrorCode.INVALID_CLUB_TIER.asException();
   176	        }
   177	        return strategy;
   178	    }
   179	
   180	    private ShippingStrategy.ShippingResult calculateShipping(
   181	            OrderRequest request, Weight totalWeight, ClubTierStrategy clubStrategy) {
   182	
   183	        if (request.region() == null) {
   184	            throw ErrorCode.INVALID_REGION.asException();
   185	        }
   186	
   187	        if (request.zipCode() == null || !request.zipCode().matches("\\d{8}")) {
   188	            throw ErrorCode.INVALID_ZIP_CODE.asException();
   189	        }
   190	
   191	        if (request.shippingMethod() == null) {
   192	            throw ErrorCode.INVALID_SHIPPING_METHOD.asException();
   193	        }
   194	
   195	        ShippingStrategy strategy = shippingStrategies.get(request.shippingMethod());
   196	        if (strategy == null) {
   197	            throw ErrorCode.INVALID_SHIPPING_METHOD.asException();
   198	        }
   199	
   200	        ShippingStrategy.ShippingContext context = new ShippingStrategy.ShippingContext(
   201	            request.zipCode(), totalWeight, request.region()
   202	        );
   203	
   204	        boolean available;
   205	        try {
   206	            available = strategy.isAvailable(context);
   207	        } catch (TransLogUnavailableException e) {
   208	            throw e;
   209	        }
   210	
   211	        if (!available) {
   212	            throw ErrorCode.SHIPPING_METHOD_UNAVAILABLE.asException();
   213	        }
   214	
   215	        ShippingStrategy.ShippingResult result = strategy.calculateShipping(context);
   216	
   217	        if (clubStrategy.hasFreeShipping(request.shippingMethod())) {
   218	            return new ShippingStrategy.ShippingResult(Money.zero(), result.days());
   219	        }
   220	
   221	        return result;
   222	    }
   223	
   224	    private Money calculateCouponDiscount(
   225	            OrderRequest request,
   226	            Money productsSubtotal,
   227	            Money shippingCost,
   228	            Map<String, Product> products) {
   229	
   230	        if (request.coupon() == null) {
   231	            return Money.zero();
   232	        }
   233	
   234	        CouponStrategy strategy = couponStrategies.get(request.coupon());
   235	        if (strategy == null) {
   236	            throw ErrorCode.INVALID_COUPON.asException();
   237	        }
   238	
   239	        boolean isFirstPurchase = !orderRepository.existsByCustomerCpfAndStatusIn(
   240	            request.customer().cpf(),
   241	            OrderStatus.PAID, OrderStatus.SHIPPED, OrderStatus.DELIVERED
   242	        );
   243	
   244	        List<OrderItem> items = request.items().stream()
   245	            .map(i -> new OrderItem(i.sku(), i.quantity()))
   246	            .toList();
   247	
   248	        CouponStrategy.CouponContext context = new CouponStrategy.CouponContext(
   249	            productsSubtotal, shippingCost, items, products, isFirstPurchase
   250	        );
   251	
   252	        if (!strategy.isApplicable(context)) {
   253	            throw ErrorCode.COUPON_NOT_APPLICABLE.asException();
   254	        }
   255	
   256	        Money discount = strategy.calculateDiscount(context);
   257	
   258	        Money maxDiscount = productsSubtotal.percentage(BigDecimal.valueOf(30));
   259	        return discount.min(maxDiscount);
   260	    }
   261	
   262	    private PaymentStrategy.PaymentResult calculatePayment(OrderRequest request, Money orderTotal) {
   263	        if (request.paymentMethod() == null) {
   264	            throw ErrorCode.INVALID_PAYMENT_METHOD.asException();
   265	        }
   266	
   267	        PaymentStrategy strategy = paymentStrategies.get(request.paymentMethod());
   268	        if (strategy == null) {
   269	            throw ErrorCode.INVALID_PAYMENT_METHOD.asException();
   270	        }
   271	
   272	        if (!strategy.isValidInstallments(request.getInstallments())) {
   273	            throw ErrorCode.INVALID_INSTALLMENTS.asException();
   274	        }
   275	
   276	        PaymentStrategy.PaymentContext context = new PaymentStrategy.PaymentContext(
   277	            orderTotal, request.getInstallments(), request.coupon() != null
   278	        );
   279	
   280	        if (!strategy.isAvailable(context)) {
   281	            throw ErrorCode.PAYMENT_METHOD_UNAVAILABLE.asException();
   282	        }
   283	
   284	        return strategy.calculatePayment(context);
   285	    }
   286	}
