=== service/payment/CreditCardPayment.java
     1	package com.loja.service.payment;
     2	
     3	import com.loja.domain.Money;
     4	import com.loja.domain.PaymentMethod;
     5	import org.springframework.stereotype.Component;
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	
     9	@Component
    10	public class CreditCardPayment implements PaymentStrategy {
    11	
    12	    private static final BigDecimal MONTHLY_INTEREST_RATE = new BigDecimal("0.0199");
    13	
    14	    @Override
    15	    public PaymentMethod getMethod() {
    16	        return PaymentMethod.CREDIT_CARD;
    17	    }
    18	
    19	    @Override
    20	    public boolean isAvailable(PaymentContext context) {
    21	        return true;
    22	    }
    23	
    24	    @Override
    25	    public boolean isValidInstallments(int installments) {
    26	        return installments >= 1 && installments <= 12;
    27	    }
    28	
    29	    @Override
    30	    public PaymentResult calculatePayment(PaymentContext context) {
    31	        if (context.installments() <= 3) {
    32	            Money installmentAmount = context.orderTotal().divide(context.installments());
    33	            return new PaymentResult(Money.zero(), context.orderTotal(), installmentAmount);
    34	        }
    35	
    36	        BigDecimal rate = MONTHLY_INTEREST_RATE;
    37	        int n = context.installments();
    38	
    39	        BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
    40	        BigDecimal powerFactor = onePlusRate.pow(n);
    41	
    42	        BigDecimal denominator = BigDecimal.ONE.subtract(
    43	            BigDecimal.ONE.divide(powerFactor, 10, RoundingMode.HALF_EVEN)
    44	        );
    45	
    46	        BigDecimal installmentValue = context.orderTotal().value()
    47	            .multiply(rate)
    48	            .divide(denominator, 2, RoundingMode.HALF_EVEN);
    49	
    50	        Money installmentAmount = new Money(installmentValue);
    51	        Money finalTotal = installmentAmount.multiply(context.installments());
    52	        Money adjustment = finalTotal.subtract(context.orderTotal());
    53	
    54	        return new PaymentResult(adjustment, finalTotal, installmentAmount);
    55	    }
    56	}
